('<lesson_id>', 'text', replace($blk${"html": "<h3>Замечательно! 👏</h3><p>Мы с тобой посмотрели видео, а теперь настало время потрудиться! Посмотри на предложения ниже и выбери правильный вариант для каждого пропуска.</p>"}$blk$, '@@MEDIA@@', 'https://classroom.wowteach.ru/media/')::jsonb, 5),
('<lesson_id>', 'quiz', replace($blk${"title": "Выбери правильный вариант для каждого пропуска", "questions": [{"q": "1. My sister ___ a hobby.", "type": "single", "options": [{"text": "don't have"}, {"text": "doesn't have"}, {"text": "doesn't has"}], "correct": [1]}, {"q": "2. They ___ my pictures.", "type": "single", "options": [{"text": "don't likes"}, {"text": "doesn't like"}, {"text": "don't like"}], "correct": [2]}, {"q": "3. David ___ karate.", "type": "single", "options": [{"text": "doesn't do"}, {"text": "don't does"}, {"text": "doesn't does"}], "correct": [0]}, {"q": "4. My parents ___ tennis.", "type": "single", "options": [{"text": "don't plays"}, {"text": "doesn't play"}, {"text": "don't play"}], "correct": [2]}, {"q": "5. She ___ French at school.", "type": "single", "options": [{"text": "doesn't study"}, {"text": "don't study"}, {"text": "doesn't studies"}], "correct": [0]}, {"q": "6. My grandfather ___ chess.", "type": "single", "options": [{"text": "doesn't plays"}, {"text": "doesn't play"}, {"text": "don't play"}], "correct": [1]}]}$blk$, '@@MEDIA@@', 'https://classroom.wowteach.ru/media/')::jsonb, 6),
('<lesson_id>', 'text', replace($blk${"html": "<h3>Отличная работа! 💪</h3><p>Давай немного переведём дух и сыграем в игру. Твоя задача — заполнить пропуски!</p>"}$blk$, '@@MEDIA@@', 'https://classroom.wowteach.ru/media/')::jsonb, 7),
('<lesson_id>', 'gaps', replace($blk${"title": "Do or does? Do or play? Перетащи слова в пропуски", "mode": "drag", "text": "1. __Do__ you play tennis at the weekend?\n2. __Does__ your brother do karate?\n3. My sister __does__ ballet on Mondays.\n4. We __play__ chess after school.\n5. Max doesn't __play__ football in his free time.\n6. I __do__ my homework in the evening."}$blk$, '@@MEDIA@@', 'https://classroom.wowteach.ru/media/')::jsonb, 8),
